"""PreToolUse hook: refuse edits to generated, secret or append-only files.

Registered for ``Edit|Write|MultiEdit|NotebookEdit`` and for ``Bash`` (design C
§5.4). Blocks, with exit 2 and the reason:

* ``src/packages/seed/fcrm_seed/seed.json`` - generated by gen_seed.py (ADR-16);
* ``src/web/src/api/generated/**`` - generated by ``make api-gen``;
* any ``.env`` / ``.env.*`` file except ``.env.example`` (and ``.envrc*``);
* anything under ``AEO/secrets`` and any ``.env*`` under EVOQ_Applications;
* changes to existing table rows in ``docs/governance/*.md`` (append-only:
  adding rows is allowed, editing or deleting one is not);
* Bash commands that read ``.env*`` or ``AEO/secrets`` or write to a
  protected path.

Run standalone: ``python3 ai/guidance/hooks/protect_paths.py < payload.json``.
"""

from __future__ import annotations

import fnmatch
import re
import sys
from pathlib import Path
from typing import Any, Optional

sys.path.insert(0, str(Path(__file__).resolve().parent))

from _hooklib import (  # noqa: E402
    allow,
    block,
    read_payload,
    relative_to_repo,
    repo_root,
    tool_input,
)

SEED_WHY = (
    "seed.json is generated by gen_seed.py; change gen_seed.py and regenerate (ADR-16)"
)
GENERATED = {
    "src/packages/seed/fcrm_seed/seed.json": SEED_WHY,
    "src/packages/fcrm_seed/seed.json": SEED_WHY,  # path named in design C §5.4
}
GENERATED_GLOBS = {
    "src/web/src/api/generated/*": (
        "the web API client is generated by `make api-gen`; "
        "change the OpenAPI source instead"
    ),
}
GOVERNANCE_GLOB = "docs/governance/*.md"
SECRET_PATH_RE = re.compile(
    r"(^|/)AEO/secrets(/|$)|EVOQ_Applications/.*(^|/)\.env[^/]*$"
)
ENV_NAME_RE = re.compile(r"^\.env(rc)?(\..+)?$")
ENV_ALLOWED = {".env.example"}
BASH_SECRET_RE = re.compile(
    r"AEO/secrets"
    r"|(^|[\s'\"=/<>(])\.env(rc)?(\.(?!example\b)[\w.-]+)?(?=$|[\s'\";|&)<>])"
)
TABLE_ROW_RE = re.compile(r"^\|.*\|\s*$")
SEPARATOR_RE = re.compile(r"^\|[\s:|-]+\|\s*$")


def protected_reason(rel: str) -> Optional[str]:
    """Why a repository-relative path may not be edited, or None."""
    if rel in GENERATED:
        return f"{rel}: {GENERATED[rel]}"
    for pattern, why in GENERATED_GLOBS.items():
        if fnmatch.fnmatch(rel, pattern) or rel.startswith(pattern[:-1]):
            return f"{rel}: {why}"
    name = Path(rel).name
    if ENV_NAME_RE.match(name) and name not in ENV_ALLOWED:
        return f"{rel}: agents never read or write environment files (CLAUDE.md)"
    if SECRET_PATH_RE.search(rel):
        return f"{rel}: AEO secrets and EVOQ .env files are off limits (CLAUDE.md)"
    return None


def table_rows(text: str) -> list[str]:
    """Data rows of Markdown tables (header separators excluded)."""
    rows = []
    for line in text.splitlines():
        stripped = line.rstrip()
        if TABLE_ROW_RE.match(stripped) and not SEPARATOR_RE.match(stripped):
            rows.append(stripped)
    return rows


def removed_rows(before: str, after: str) -> list[str]:
    """Rows present in `before` that are missing from `after` (multiset)."""
    remaining = table_rows(after)
    missing = []
    for row in table_rows(before):
        if row in remaining:
            remaining.remove(row)
        else:
            missing.append(row)
    return missing


def governance_violation(
    rel: str, root: Path, tool: str, args: dict[str, Any]
) -> Optional[str]:
    """Reason a governance-table edit changes or deletes an existing row."""
    if not fnmatch.fnmatch(rel, GOVERNANCE_GLOB):
        return None
    path = root / rel
    if tool == "Write":
        if not path.exists():
            return None
        current = path.read_text(encoding="utf-8")
        missing = removed_rows(current, str(args.get("content", "")))
    else:
        edits = args.get("edits") if tool == "MultiEdit" else [args]
        missing = []
        for edit in edits or []:
            if isinstance(edit, dict):
                missing += removed_rows(
                    str(edit.get("old_string", "")), str(edit.get("new_string", ""))
                )
    if not missing:
        return None
    first = missing[0][:120]
    return (
        f"{rel} is append-only: this edit changes or removes {len(missing)} "
        f"existing row(s), e.g. `{first}`. Append a new row instead "
        "(a superseding row references the old one)."
    )


def check_file_tool(tool: str, args: dict[str, Any], root: Path) -> None:
    """Block Edit/Write/MultiEdit/NotebookEdit on protected paths."""
    target = args.get("file_path") or args.get("notebook_path") or args.get("path")
    if not isinstance(target, str) or not target:
        allow()
    rel = relative_to_repo(target, root)
    reason = protected_reason(rel) or governance_violation(rel, root, tool, args)
    if reason:
        block(reason)
    allow()


def writes_to(command: str, target: str, allow_append: bool = False) -> bool:
    """True if a shell command writes to a path containing `target`."""
    t = re.escape(target)
    seg = r"[^;|&\n]*"
    redirect = r">" if allow_append else r">>?"
    patterns = [
        rf"(?<!>){redirect}\s*\S*{t}",  # > path  (and >> unless appends are allowed)
        rf"\btee\b(?!\s+-a){seg}\S*{t}",  # tee path (tee -a is an append)
        rf"\bsed\s+(-\w*\s+)*-i{seg}{t}",  # sed -i ... path
        rf"\b(rm|truncate|perl\s+-pi){seg}{t}",  # rm path, truncate path
        # cp/mv/install ... path, with the path as the destination (last word)
        rf"\b(cp|mv|install)\s{seg}\s\S*{t}\S*\s*($|[;|&\n])",
    ]
    return any(re.search(p, command) for p in patterns)


def check_bash(args: dict[str, Any], root: Path) -> None:
    """Block shell commands that read secrets or write protected paths."""
    command = str(args.get("command", ""))
    if BASH_SECRET_RE.search(command):
        block("command touches a .env file or AEO/secrets; agents never read these")
    for rel in [*GENERATED, "src/web/src/api/generated/"]:
        if writes_to(command, rel) or (
            rel.endswith("seed.json") and writes_to(command, "fcrm_seed/seed.json")
        ):
            block(
                f"command writes to a generated path ({rel}); "
                "regenerate it with its generator instead"
            )
    if writes_to(command, "docs/governance/", allow_append=True):
        block(
            "docs/governance tables are append-only; append a row with the Edit "
            "tool or `>>`, never rewrite one"
        )
    allow()


def main() -> None:
    """Entry point: dispatch on tool_name."""
    payload = read_payload()
    root = repo_root(payload)
    tool = str(payload.get("tool_name", ""))
    args = tool_input(payload)
    if tool in {"Edit", "Write", "MultiEdit", "NotebookEdit"}:
        check_file_tool(tool, args, root)
    if tool == "Bash":
        check_bash(args, root)
    allow()


if __name__ == "__main__":
    main()
